import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer, ErrorMessage } from 'components';
import { useCurrentPage, usePageFilterApplied, usePageFilterData } from 'hooks';

import { formatScopedGeoTitle } from '../../../../utils/formatScopedGeoTitle';
import { useInnovationHubPortfolioData } from '../../hooks';
import type { PortfolioCardData, PortfolioPieChartData } from '../../types';
import { PortfolioBigNumbers } from '../PortfolioBigNumbers';
import { PortfolioPieChart } from '../PortfolioPieChart';
import {
  StyledInnovationPortfolioRoot,
  StyledPieChartsRow,
  StyledPieChartsState,
} from './InnovationPortfolio.styles';

/** Max portfolio donut cards (loading placeholders only; order comes from BFF). */
const PORTFOLIO_PIE_CHART_SKELETON_COUNT = 3;

export interface InnovationPortfolioProps {
  dataTestId?: string;
  mockPortfolioBigNumbers?: PortfolioCardData[];
  mockPortfolioPieCharts?: PortfolioPieChartData[];
}

export const InnovationPortfolio: React.FC<InnovationPortfolioProps> = ({
  dataTestId,
  mockPortfolioBigNumbers: mockBigNumbers,
  mockPortfolioPieCharts: mockPieCharts,
}) => {
  const { formatMessage } = useIntl();
  const { currentPage } = useCurrentPage();
  const { applied } = usePageFilterApplied(currentPage);
  const { dataFilters } = usePageFilterData(currentPage);
  const {
    bigNumbers: bffBigNumbers,
    pieCharts: bffPieCharts,
    loading,
    error,
  } = useInnovationHubPortfolioData();

  const sectionTitle = useMemo(
    () =>
      formatScopedGeoTitle(formatMessage, {
        applied,
        dataFilters,
        globalTitleId: 'Innovation.InnovationHub.Overview.Portfolio.title',
        scopedTitleId:
          'Innovation.InnovationHub.Overview.Portfolio.sectionTitle',
      }),
    [applied, dataFilters, formatMessage],
  );

  const hasBigNumbersMock = Boolean(mockBigNumbers?.length);
  const hasPieChartsMock = Boolean(mockPieCharts?.length);

  const bigNumbers = mockBigNumbers?.length ? mockBigNumbers : bffBigNumbers;
  const pieError = hasPieChartsMock ? null : error;
  let pieCharts: PortfolioPieChartData[] = [];

  if (mockPieCharts?.length) {
    pieCharts = mockPieCharts;
  } else if (!pieError) {
    pieCharts = bffPieCharts;
  }

  const bigNumbersLoading = hasBigNumbersMock ? false : loading;
  const pieLoading = hasPieChartsMock ? false : loading;
  const bigNumbersError = hasBigNumbersMock ? null : error;

  const showPieSkeletons =
    pieLoading && !hasPieChartsMock && !pieError && pieCharts.length === 0;

  let pieChartsContent: React.ReactNode = pieCharts.map((chart) => (
    <PortfolioPieChart
      key={chart.id}
      chartId={chart.id}
      title={chart.title}
      slices={chart.slices}
      loading={pieLoading}
      dataTestId={`portfolio-pie-chart-${chart.id}`}
    />
  ));

  if (pieError) {
    pieChartsContent = (
      <StyledPieChartsState>
        <ErrorMessage dataTestId="innovation-portfolio-pie-charts-error" />
      </StyledPieChartsState>
    );
  } else if (showPieSkeletons) {
    pieChartsContent = Array.from(
      { length: PORTFOLIO_PIE_CHART_SKELETON_COUNT },
      (_, index) => (
        <PortfolioPieChart
          key={`pie-skeleton-${index}`}
          chartId="liquidType"
          title=""
          slices={[]}
          loading
          dataTestId={`portfolio-pie-chart-skeleton-${index}`}
        />
      ),
    );
  }

  return (
    <StyledInnovationPortfolioRoot data-testid={dataTestId}>
      <BasicContainer
        dataTestId="innovation-portfolio"
        layout={{
          background: '#fafafa',
          border: 'gray',
          bodyPadding: false,
        }}
        header={{
          title: sectionTitle,
          titleSize: 'H1',
        }}
      >
        <PortfolioBigNumbers
          data={bigNumbers}
          loading={bigNumbersLoading}
          error={bigNumbersError}
        />
        <StyledPieChartsRow>{pieChartsContent}</StyledPieChartsRow>
      </BasicContainer>
    </StyledInnovationPortfolioRoot>
  );
};
